// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }

    // fuzzed params: depositor private key, deposit amount
    function testFuzz_property(uint256 depositorKey, uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        depositorKey = bound(depositorKey, 1, 115792089237316195423570985008687907852837564279074904382605163141518161494336);
        // keep domains reasonable but wide
        vm.assume(amount > 0 && amount < 1 ether);
        // derive depositor address from key so we can sign/prank as them
        address depositor = vm.addr(uint256(depositorKey));
        vm.deal(depositor, amount + 1 wei);

        // Deploy a reentrant receiver that will re-enter c.withdrawAll once during the external call
        Reenterer re = new Reenterer(c);

        // depositor deposits amount into c
        vm.prank(depositor);
        c.deposit{value: amount}();

        // transfer the deposited credit to the reenterer: we simulate that depositor's credit is used by making
        // the reenterer be the msg.sender for withdrawAll; to create the scenario where withdrawAll is called
        // on behalf of the reenterer, first deposit from reenterer too.
        vm.deal(address(re), 0);
        // give reenterer some ETH so that it can receive the callback and not fail for lack of balance
        vm.deal(address(re), 0);

        // Now, we need the reenterer to have credit in c. Have depositor transfer funds to reenterer by calling deposit from reenterer
        // But we cannot move depositor's credit to reenterer directly; instead, make reenterer deposit itself so it has credit to withdraw
        // Make reenterer deposit 'amount' as well (fund reenterer first)
        vm.deal(address(re), amount + 1 wei);
        vm.prank(address(re));
        c.deposit{value: amount}();

        // At this point both depositor and reenterer have credit = amount. We'll test behavior when reenterer calls withdrawAll,
        // and during the external transfer it will re-enter withdrawAll once.

        // Ensure reenterer sees non-zero credit before
        // No direct getter exists for mapping credit, so we infer by attempting withdrawAll with try/catch and observing success and balance

        // Record c balance before
        uint256 beforeBalance = address(c).balance;

        // Trigger withdrawAll from reenterer; it will attempt to re-enter during receiving the funds
        bool ok;
        vm.prank(address(re));
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // After a successful withdrawAll on the reference, the reenterer's credit MUST be zero (so a second withdrawAll should do nothing and succeed trivially).
        // We express that by calling withdrawAll again: on the reference it should succeed and do nothing (ok2 == true), and address(c).balance should not decrease further.

        // Capture balance before second attempt
        uint256 midBalance = address(c).balance;

        // Second attempt to withdrawAll from reenterer
        bool ok2;
        vm.prank(address(re));
        try c.withdrawAll() {
            ok2 = true;
        } catch {
            ok2 = false;
        }

        uint256 afterBalance = address(c).balance;

        // The general rule: if the first withdrawAll returned successfully (ok == true), then the second withdrawAll should also succeed (ok2 == true) and must not change c's balance further (midBalance == afterBalance).
        // The mutant that fails to zero the credit can allow the reentrant callback to withdraw again or cause different behavior; the reentrant scenario can make ok2 == false or midBalance != afterBalance.
        assertTrue(!(ok && (ok2 == false || midBalance != afterBalance)));
    }
}

// Reentrant helper: when it receives ETH, it will re-enter c.withdrawAll exactly once.
contract Reenterer {
    ReentrancyDAO c;
    bool entered;
    constructor(ReentrancyDAO _c) {
        c = _c;
    }
    receive() external payable {
        if (!entered) {
            entered = true;
            // re-enter withdrawAll once
            // use try/catch to avoid bubbling revert to original call
            try c.withdrawAll() {
                // ignore
            } catch {
                // ignore
            }
        }
    }
}
